using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BMRepair {
 static string H=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B2_FullFloor/"));const string A="Assets/Afrer_Seconds/05.Model/";
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var fire=all.Single(t=>t.name=="B2_C02_WallSafety_01");float a=-15*Mathf.Deg2Rad;var d=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));fire.localPosition=d*(Mathf.Sqrt(121-2.13f*2.13f)-.20f);fire.localRotation=Quaternion.LookRotation(-d);PrefabUtility.RecordPrefabInstancePropertyModifications(fire);
 var rack=all.Single(t=>t.name=="B2_W03_EquipmentCaseRack_13");rack.localPosition-=rack.localPosition.normalized*.65f;PrefabUtility.RecordPrefabInstancePropertyModifications(rack);var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var p=plan["placements"].Single(p=>(string)p["name"]==rack.name);p["position"]=JArray.FromObject(new[]{rack.localPosition.x,rack.localPosition.y,rack.localPosition.z});File.WriteAllText(H+"layout.json",plan.ToString());
 int mats=0;foreach(var t in all.Where(t=>t.name.EndsWith("_Visual")&&(t.name.Contains("Centrifuge")||t.name.Contains("ElectricalCabinet")||t.name.Contains("ControlConsole")))){string prefix=t.name.Contains("Centrifuge")?"Props_IndustrialCentrifuge_Material_URP":t.name.Contains("Electrical")?"Props_ElectricalCabinet_Material_URP":"B2_ControlDeskIsland_URP";var path=AssetDatabase.FindAssets(prefix+" t:Material").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault();if(path==null)continue;var material=AssetDatabase.LoadAssetAtPath<Material>(path);foreach(var r in t.GetComponentsInChildren<MeshRenderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>material).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(r);}mats++;}
 var root=all.Single(t=>t.name=="B2_MachineryNetwork");int bounce=0;foreach(var fixture in root.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("_PipeWorkLight_")).ToArray()){var g=new GameObject("IndirectPipeBounce");g.transform.SetParent(fixture,false);g.transform.localPosition=new Vector3(0,-.9f,0);var l=g.AddComponent<Light>();l.type=LightType.Point;l.intensity=.8f;l.range=8.2f;l.color=new Color(.73f,.81f,.88f);l.shadows=LightShadows.None;bounce++;}
 EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{moved=new[]{fire.name,rack.name},pbrRestored=mats,bounceLights=bounce};}
